// Final audit record. Both branches arrive here with the same flat shape.
const s = $input.first().json;
return [{
  json: {
    onboardingId: s.onbId,
    ticketId: s.ticketId || null,
    employee: {
      name: s.employeeName,
      email: s.employeeEmail || null,
